import * as React from 'react';

/**
 * Whether the thing on screen is worth running a clock for: the tab is visible and the node is in view.
 * Returns a ref callback to put on the node and the answer. Anything that ticks on a timer while nobody can
 * see it should gate on this, so a page at rest costs nothing.
 */
export function useAwake(): [(el: Element | null) => void, boolean] {
  const [el, setEl] = React.useState<Element | null>(null);
  const [seen, setSeen] = React.useState(true);
  const [shown, setShown] = React.useState(() => typeof document === 'undefined' || !document.hidden);
  React.useEffect(() => {
    if (!el) return;
    const watch = new IntersectionObserver((entries) => setSeen(entries[entries.length - 1]?.isIntersecting ?? true)); // the latest entry is the current truth
    const visibility = () => setShown(!document.hidden);
    watch.observe(el);
    document.addEventListener('visibilitychange', visibility);
    visibility();
    return () => { watch.disconnect(); document.removeEventListener('visibilitychange', visibility); };
  }, [el]);
  return [setEl, seen && shown];
}

/* ─────────────────────────────────────────────────────────
 * HAPTIC (the web's share of the tap you feel when something catches)
 *
 *   alignment  a snap caught a new line (Snap guides): one short tick
 *   detent     a value landed on a stop (a detent): one firmer tick
 *   refusal    a thing would not do what was asked: two ticks
 *
 * One call per catch, never one per frame. The first path that exists wins:
 *   bridge      a web-view host (Electron, Tauri, WKWebView) set one with setHapticBridge:
 *               it plays the platform haptic (NSHapticFeedbackManager on a Mac trackpad)
 *   vibrate     navigator.vibrate on a touch device that has it (Android)
 *   ios-switch  iOS Safari 17.4+: toggling a hidden <input type="checkbox" switch> plays
 *               the system tick (feature-detected; a touch device only, since a Mac's
 *               Safari has the switch but no haptic)
 *   none        everywhere else (a Mac or PC browser): nothing plays, and nothing stands in
 *               for it. Never replace a haptic with a sound or a flash.
 * Returns the path it took, so a host can say honestly what the person felt.
 * ───────────────────────────────────────────────────────── */

export type HapticKind = 'alignment' | 'detent' | 'refusal';
export type HapticPath = 'bridge' | 'vibrate' | 'ios-switch' | 'none';
/** A host's native haptic. Called once per catch with the kind; see the Snap guides agent guide. */
export type HapticBridge = (kind: HapticKind) => void;

/** navigator.vibrate patterns in ms: short enough to read as a tick, not a buzz. */
const VIBRATE: Record<HapticKind, number | number[]> = { alignment: 8, detent: 12, refusal: [10, 60, 10] };
/** Switch toggles per kind, and the gap between them (ms). */
const TICKS: Record<HapticKind, number> = { alignment: 1, detent: 1, refusal: 2 };
const TICK_GAP = 80;

let bridge: HapticBridge | null = null;
let bridgeVersion = 0;

/** Route haptic() to the host's native haptic (a web view in a Mac app), or back to the web with null. */
export function setHapticBridge(fn: HapticBridge | null) {
  bridge = fn;
  const installed = ++bridgeVersion;
  // A disposed host must never clear a newer host's transport.
  return () => {
    if (bridgeVersion === installed) { bridge = null; bridgeVersion++; }
  };
}

/** Opt into the shipped WKWebView host handler. SSR and ordinary browsers return null. */
export function connectWebKitHaptics(): (() => void) | null {
  if (typeof window === 'undefined') return null;
  const host = window as Window & { webkit?: { messageHandlers?: { metaluiHaptic?: { postMessage(kind: HapticKind): void } } } };
  const handler = host.webkit?.messageHandlers?.metaluiHaptic;
  if (typeof handler?.postMessage !== 'function') return null;
  return setHapticBridge(kind => handler.postMessage(kind));
}

const coarse = () => typeof matchMedia === 'function' && matchMedia('(pointer: coarse)').matches;

let label: HTMLLabelElement | null = null;
function tickSwitch() {
  if (!label || !label.isConnected) {
    label = document.createElement('label');
    label.setAttribute('aria-hidden', 'true');
    label.dataset.muHaptic = '';
    label.style.display = 'none';
    const input = document.createElement('input');
    input.type = 'checkbox';
    input.setAttribute('switch', '');
    input.tabIndex = -1;
    label.appendChild(input);
    document.body.appendChild(label);
  }
  label.click(); // a label click toggles its switch, and iOS plays the tick
}

/** Play the haptic for a catch where this platform can, and say which path it took. */
export function haptic(kind: HapticKind): HapticPath {
  if (bridge) {
    bridge(kind);
    return 'bridge';
  }
  if (typeof window === 'undefined' || typeof document === 'undefined') return 'none';
  if (!coarse()) return 'none';
  if (typeof navigator.vibrate === 'function') {
    // false: the browser refused (no user activation yet, or vibration is off)
    return navigator.vibrate(VIBRATE[kind]) ? 'vibrate' : 'none';
  }
  if ('switch' in HTMLInputElement.prototype) {
    tickSwitch();
    for (let i = 1; i < TICKS[kind]; i++) window.setTimeout(tickSwitch, TICK_GAP * i);
    return 'ios-switch';
  }
  return 'none';
}

/* ─────────────────────────────────────────────────────────
 * HOP: a thing thrown from one stop to the next along a small arc
 *
 * For a light stepping down a list, or an object moving from one region to another.
 * It travels a quadratic arc: the control point sits off the middle of the straight line by
 * min(0.8 × distance, --mu-motion-hop-lift), so the arc peaks at half that (7 px at most).
 *   side   up   bows toward the top of the screen, like a thrown thing (moves between regions);
 *               a mostly vertical move bows to the left going down, right going up
 *          cw / ccw  locked to the direction of travel (a light down a list uses ccw)
 *   reach  near  a light stepping through a list: the arc is capped by --mu-motion-hop-lift,
 *                in --mu-motion-hop-duration (250 ms), easing out
 *          far   a thing carried to another place, thrown with weight:
 *                  crouch  --mu-motion-hop-crouch (70 ms): it presses into the table
 *                  flight  --mu-motion-hop-duration-far (340 ms): across smoothly, while its height
 *                          follows gravity (rises slowing, hangs, falls faster); it grows to
 *                          --mu-motion-hop-rise and casts --mu-motion-hop-rise-shadow at the top
 *                  land    --mu-motion-hop-land (200 ms): squashes to --mu-motion-hop-squash on its
 *                          base, rebounds and settles (the table is a stop, so it may bounce)
 * Reduce Motion: it jumps. The last frame is held, so the caller sets the resting place.
 * ───────────────────────────────────────────────────────── */

export interface HopPoint { x: number; y: number }
export interface HopOptions { side?: 'up' | 'cw' | 'ccw'; reach?: 'near' | 'far' }

const FRAMES = 24;

function token(name: string, fallback: number) {
  if (typeof window === 'undefined') return fallback;
  const v = parseFloat(getComputedStyle(document.documentElement).getPropertyValue(name));
  return Number.isFinite(v) ? v : fallback;
}

/** The point a fraction t (0–1) of the way along the hop's arc. */
export function hopPoint(from: HopPoint, to: HopPoint, t: number, { side = 'up' }: HopOptions = {}, lift = 14): HopPoint {
  const dx = to.x - from.x, dy = to.y - from.y, d = Math.hypot(dx, dy);
  if (d === 0) return to;
  // ccw bows to the left of travel on screen (y grows down): going down it bows left, going up right.
  let nx = -dy / d, ny = dx / d;
  if (side === 'cw') { nx = -nx; ny = -ny; }
  // up bows toward the top of the screen; a mostly vertical move keeps ccw.
  if (side === 'up' && Math.abs(dx) >= Math.abs(dy) && ny > 0) { nx = -nx; ny = -ny; }
  const h = Math.min(token('--mu-motion-hop-arc-ratio', 0.8) * d, lift);
  const cx = from.x + dx / 2 + nx * h, cy = from.y + dy / 2 + ny * h;
  const u = 1 - t;
  return { x: u * u * from.x + 2 * u * t * cx + t * t * to.x, y: u * u * from.y + 2 * u * t * cy + t * t * to.y };
}

/** Throws the element from one translate to another along the hop's arc. Returns the animation. */
export function hop(el: HTMLElement, from: HopPoint, to: HopPoint, options: HopOptions = {}): Animation {
  const reduced = typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (options.reach === 'far') return throwFar(el, from, to, options, reduced);
  const duration = reduced ? 0 : token('--mu-motion-hop-duration', 250);
  const lift = token('--mu-motion-hop-lift', 14);
  const frames: Keyframe[] = [];
  for (let k = 0; k <= FRAMES; k++) {
    const time = k / FRAMES, t = 1 - (1 - time) * (1 - time); // ease out: fast from the stop, slow into the next
    const p = hopPoint(from, to, t, options, lift);
    frames.push({ offset: time, transform: `translate(${p.x}px, ${p.y}px)` });
  }
  return el.animate(frames, { duration, easing: 'linear', fill: 'forwards' });
}

function cssToken(name: string, fallback: string) {
  if (typeof window === 'undefined') return fallback;
  return getComputedStyle(document.documentElement).getPropertyValue(name).trim() || fallback;
}

/* A far hop: crouch, a throw under gravity, a landing that squashes and settles. One animation, so a
 * caller can cancel it and set the resting place like any other. */
function throwFar(el: HTMLElement, from: HopPoint, to: HopPoint, _options: HopOptions, reduced: boolean): Animation {
  const at = (p: HopPoint, sx = 1, sy = 1) => `translate(${p.x}px, ${p.y}px) scale(${sx}, ${sy})`;
  const none = 'drop-shadow(0 0 0 rgba(0,0,0,0))';
  if (reduced) return el.animate([{ transform: at(to), filter: none }], { duration: 0, fill: 'forwards' });

  const crouch = token('--mu-motion-hop-crouch', 70), flight = token('--mu-motion-hop-duration-far', 340), land = token('--mu-motion-hop-land', 200);
  const rise = token('--mu-motion-hop-rise', 1.04), squash = token('--mu-motion-hop-squash', 0.95);
  const shadow = cssToken('--mu-motion-hop-rise-shadow', '0 14px 18px rgba(0,0,0,.16)');
  const total = crouch + flight + land;
  const dx = to.x - from.x, dy = to.y - from.y, d = Math.hypot(dx, dy);
  // The top of the throw (always toward the top of the screen): half the control-point lift, bounded by the distance.
  const apex = Math.min(token('--mu-motion-hop-arc-ratio', 0.8) * d, token('--mu-motion-hop-lift-far', 72)) / 2;
  // The shadow at a height h (0–1): its offset, blur and alpha grow with the height.
  const cast = (h: number) => (h <= 0 ? none : `drop-shadow(${shadow.replace(/(-?[\d.]+)px/g, (_, n) => `${(+n * h).toFixed(2)}px`).replace(/rgba\(([^)]+),\s*([\d.]+)\)/, (_, rgb, a) => `rgba(${rgb},${(+a * h).toFixed(3)})`)})`);

  const frames: Keyframe[] = [];
  el.style.transformOrigin = '50% 100%'; // it crouches and lands on its base
  // Crouch: press into the table, from rest.
  frames.push({ offset: 0, transform: at(from), filter: none, easing: 'ease-out' });
  frames.push({ offset: crouch / total, transform: at(from, 1 + (1 - squash) / 4, 1 - (1 - squash) / 2), filter: none });
  // Flight: across on a smooth ease, height on gravity (a parabola in time), scale and shadow with height.
  const N = 20;
  for (let k = 1; k <= N; k++) {
    const u = k / N;
    const across = u * u * (3 - 2 * u); // lifts off and sets down smoothly
    const h = 4 * u * (1 - u); // gravity: rises slowing, hangs, falls faster
    const p = { x: from.x + dx * across, y: from.y + dy * u - apex * h };
    const g = 1 + (rise - 1) * h;
    frames.push({ offset: (crouch + flight * u) / total, transform: at(p, g, g), filter: cast(h), easing: 'linear' });
  }
  // Land: squash on its base, rebound, settle.
  frames.push({ offset: (crouch + flight + land * 0.35) / total, transform: at(to, 1 + (1 - squash) / 2, squash), filter: none, easing: 'ease-out' });
  frames.push({ offset: (crouch + flight + land * 0.7) / total, transform: at(to, 1 - (1 - squash) / 6, 1 + (1 - squash) / 3), filter: none, easing: 'ease-in-out' });
  frames.push({ offset: 1, transform: at(to), filter: none });
  return el.animate(frames, { duration: total, fill: 'forwards' });
}

'use client';

import * as React from 'react';
import { useIsoLayoutEffect } from './layout-effect';

/* ─────────────────────────────────────────────────────────
 * SLIDING INDICATOR STORYBOARD (selection A → B in a group)
 *
 *      0ms   the thumb leaves A and travels to B's box
 *            in a track with ends (segments, tabs, switch): part spring
 *              k170 c16, near 198ms, overshoots ~9% against the stop
 *            free travel (lists, navigation): settle spring k380 c36,
 *              near 214ms, no overshoot: nothing to bounce against
 *      0ms   A's label fades to ink2, B's to ink
 * First paint, resize and font load: the thumb is placed without motion.
 * Reduced motion: the thumb moves instantly; labels still recolor.
 * ───────────────────────────────────────────────────────── */

/* Selection glide (Transitions T3): the selection is a part that travels, on the part spring; free
 * travel has no stop to bounce against, so it settles. Reduce Motion: it moves at once. */
const INDICATOR = 'mu-indicator absolute top-0 left-0 z-0 pointer-events-none data-animate:indicator-glide data-animate:data-[spring=settle]:indicator-glide-settle data-animate:motion-reduce:transition-none';
const activeItem = '[aria-checked="true"],[aria-selected="true"],[aria-current="page"]';
const ariaState = ['aria-checked', 'aria-selected', 'aria-current'];

export interface SlidingIndicatorProps {
  /** Selects the active item inside the group. Defaults to ARIA checked/selected/current. */
  activeSelector?: string;
  /** The indicator's material and shape, e.g. "material-thumb rounded-pill". */
  className?: string;
  /**
   * "part" when the thumb rides a track with ends (switcher, tabs, switch): it may
   * overshoot against the stop. "settle" for free travel (lists, navigation).
   */
  spring?: 'part' | 'settle';
  /** The attributes that mark the active item. Defaults to the ARIA ones; a list highlight watches data-highlighted. */
  watch?: string[];
}

/**
 * A thumb that glides to the active item of its parent group: switcher
 * controls, tabs, navigation. Place it as the first child of a positioned
 * group; it follows ARIA state, so the items stay ordinary buttons or links.
 */
export function SlidingIndicator({ activeSelector = activeItem, className, spring = 'part', watch = ariaState }: SlidingIndicatorProps) {
  const self = React.useRef<HTMLSpanElement>(null);
  const [box, setBox] = React.useState<{ x: number; y: number; w: number; h: number; animate: boolean; shown: boolean } | null>(null);
  const watched = watch.join(' ');

  useIsoLayoutEffect(() => {
    const el = self.current?.parentElement;
    if (!el) return;
    const place = (animate: boolean) => {
      const active = el.querySelector<HTMLElement>(activeSelector);
      // With nothing active it hides where it was, so the next arrival starts in place, not from the corner.
      if (!active) return setBox((b) => (b ? { ...b, shown: false } : null));
      // offset* ignore transforms, so the measurement is stable mid-animation.
      let x = 0, y = 0, node: HTMLElement | null = active;
      while (node && node !== el) { x += node.offsetLeft; y += node.offsetTop; node = node.offsetParent as HTMLElement | null; }
      setBox((b) => ({ x, y, w: active.offsetWidth, h: active.offsetHeight, animate: animate && !!b?.shown, shown: true }));
    };
    place(false);
    const mo = new MutationObserver(() => place(true));
    mo.observe(el, { subtree: true, attributes: true, attributeFilter: watched.split(' ') });
    const ro = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(() => place(false)) : null;
    ro?.observe(el);
    return () => { mo.disconnect(); ro?.disconnect(); };
  }, [activeSelector, watched]);

  return (
    <span
      ref={self}
      aria-hidden="true"
      className={className ? `${INDICATOR} ${className}` : INDICATOR}
      data-animate={box?.animate || undefined}
      data-spring={spring}
      style={box?.shown ? { width: box.w, height: box.h, transform: `translate(${box.x}px, ${box.y}px)` } : { visibility: 'hidden' }}
    />
  );
}

import * as React from 'react';

/** useLayoutEffect in the browser, useEffect on the server: React 18 warns when a layout effect renders on the server. */
export const useIsoLayoutEffect = typeof window === 'undefined' ? React.useEffect : React.useLayoutEffect;

import { motionReduced, subscribeMotionPreference } from './reduced';

export interface RowLeaveOptions {
  /** Capture the list's layout before the row leaves. Called once, including under Reduce Motion. */
  onStart?: () => void;
}

const pending = new WeakMap<HTMLElement, () => void>();

/** Leave one nest down on the release spring, then let the host remove the row.
 * Reduced motion removes it at once. Return the cancellation for an effect cleanup.
 * Repeated calls while leaving share the original operation and never call its completion twice.
 */
export function leaveRow(element: HTMLElement | null, onLeft: () => void, options: RowLeaveOptions = {}): () => void {
  if (!element) { options.onStart?.(); onLeft(); return () => {}; }
  const current = pending.get(element);
  if (current) return current;
  const style = getComputedStyle(element);
  const durationText = style.getPropertyValue('--mu-spring-release-d').trim();
  const duration = parseFloat(durationText) * (durationText.endsWith('ms') ? 1 : 1000);
  const travel = parseFloat(style.getPropertyValue('--mu-motion-nest')) * (parseFloat(style.getPropertyValue('--mu-travel-settle')) || 0);
  let animation: Animation | undefined;
  let unsubscribe = () => {};
  let finished = false;
  const finish = (complete: boolean) => {
    if (finished) return;
    finished = true;
    unsubscribe();
    animation?.cancel();
    pending.delete(element);
    if (complete) onLeft();
  };
  const cancel = () => finish(false);
  pending.set(element, cancel);
  options.onStart?.();
  if (motionReduced(element) || !Number.isFinite(duration) || duration <= 0 || typeof element.animate !== 'function') {
    finish(true);
    return cancel;
  }
  animation = element.animate(
    [{ opacity: 1, transform: 'translateY(0)' }, { opacity: 0, transform: `translateY(${Number.isFinite(travel) ? travel : 0}px)` }],
    { duration, easing: style.getPropertyValue('--mu-spring-release').trim() || 'ease-out', fill: 'forwards', id: 'mu-row-leave' },
  );
  animation.onfinish = () => finish(true);
  animation.oncancel = () => finish(false);
  unsubscribe = subscribeMotionPreference(element, () => { if (motionReduced(element)) finish(true); });
  return cancel;
}

'use client';

import * as React from 'react';
import { flushSync } from 'react-dom';

/* ─────────────────────────────────────────────────────────
 * MORPH SHAPE, one shape, many states (docs/ONE-SHAPE.md)
 *
 * Wrap the one shape whose contents change (a capsule that opens into a panel, a cap that opens
 * into a tray). Change its state with morphTo():
 *
 *     0 ms   the body's outline travels from the old box to the new on the surface spring
 *            (closing: the release spring), painted in its material, corners true
 *     0 ms   the leaving contents fade on the release spring; they do not travel
 *     0 ms   the arriving contents rise one nest from the edge the body grows from, at the
 *            popover's enter scale, on the surface spring (a MetalUI surface arriving)
 *            a part in both states (MorphPart) travels with the body instead
 *   ~500 ms  rest: the real element is back, nothing runs
 * An interrupt skips the running morph and starts from the state on screen. Travel scales by
 * --mu-travel-surface, so Reduce Motion leaves only the fades. Without View Transitions the
 * state simply changes.
 *
 * Built on the platform's View Transitions directly: a shape carries its transition name and class as
 * data attributes, and morphTo names only the shape it is given (its scope) for the length of the
 * morph, so the platform snapshots that shape and nothing else. The change commits inside the
 * transition with flushSync: nothing waits on another render, and no other render can cancel it.
 * ───────────────────────────────────────────────────────── */

export type MorphMaterial = 'graphite-deep' | 'tool' | 'pop';
export type MorphKind = 'open' | 'close';

type Running = { finished: Promise<void>; skipTransition(): void };
type Transitioning = Document & {
  startViewTransition?: (o: { update: () => void; types?: string[] }) => Running;
  activeViewTransition?: Running | null;
};

const namedShapes = '[data-morph-name]';

/** Give the shapes inside `scope` their transition names (or take them away). */
function name(scope: ParentNode, on: boolean) {
  const els = [...(scope instanceof Element && scope.matches(namedShapes) ? [scope] : []), ...scope.querySelectorAll<HTMLElement>(namedShapes)] as HTMLElement[];
  for (const el of els) {
    el.style.setProperty('view-transition-name', on ? el.dataset.morphName! : '');
    el.style.setProperty('view-transition-class', on ? el.dataset.morphClass ?? '' : '');
  }
}

/**
 * Change a shape's state as a morph: finishes a running one, names the shapes inside `scope` (the
 * shape and the parts beside it; default the whole page), and commits the change inside the
 * transition. Only what is named is snapshotted, so give the narrowest scope that holds the change.
 */
export function morphTo(update: () => void, kind?: MorphKind, scope?: Element | null) {
  const doc = typeof document !== 'undefined' ? (document as Transitioning) : null;
  if (!doc?.startViewTransition) { update(); return; }
  doc.activeViewTransition?.skipTransition();
  const root: ParentNode = scope ?? doc;
  name(root, true);
  const run = doc.startViewTransition({
    update: () => { flushSync(update); name(root, true); },
    types: kind ? [kind] : [],
  });
  run.finished.finally(() => name(root, false));
}

/** Run after the morph in flight lands (or now, if none): focus into new contents, a tooltip, a measure. */
export function afterMorph(fn: () => void) {
  const running = typeof document !== 'undefined' ? (document as Transitioning).activeViewTransition : undefined;
  if (running) running.finished.finally(fn);
  else fn();
}

/**
 * Give focus back to a morph's trigger once it lands, unless something else has taken focus since
 * (a dialog the morph opened, a control the person moved to): focus left on nothing is the only
 * focus that is ours to place.
 */
export function returnFocusAfterMorph(el: () => HTMLElement | null | undefined) {
  afterMorph(() => {
    const now = typeof document !== 'undefined' ? document.activeElement : null;
    if (!now || now === document.body) el()?.focus({ preventScroll: true });
  });
}

const css = (name: string) => name.replace(/[^a-zA-Z0-9_-]/g, '');

export interface MorphShapeProps {
  /** The one element that is the shape (it paints its own surface at rest). */
  children: React.ReactElement;
  /** The shape's material, painted on its outline while it travels. */
  material: MorphMaterial;
  /** The edge the body grows from, where the contents stay pinned: top (drops down) or left (opens sideways). */
  from?: 'top' | 'left';
  /** A name shared by the closed and open elements when they are different elements (render one at a time). */
  name?: string;
}

/**
 * The body and its contents, named for the platform's view transitions. The child is the body; its
 * own children are the contents, wrapped once so they change as one (whatever replaces them, a
 * second page included). The body gets `view-transition-group: contain` so the contents' group
 * nests inside it and is clipped by the travelling outline.
 */
export function MorphShape({ children, material, from = 'top', name }: MorphShapeProps) {
  const id = css(React.useId());
  const body = name ? css(name) : `mu-${id}-body`;
  const child = children as React.ReactElement<{ style?: React.CSSProperties; children?: React.ReactNode }>;
  const contents = (
    <span className="mu-morph-contents" data-morph-name={`mu-${id}-contents`} data-morph-class={`mu-morph-contents mu-morph-from-${from}`}>
      {child.props.children}
    </span>
  );
  return React.cloneElement(child, {
    'data-morph-name': body,
    'data-morph-class': `mu-morph-body mu-morph-${material}`,
    style: { ...child.props.style, viewTransitionGroup: 'contain' } as React.CSSProperties,
  } as Record<string, unknown>, contents);
}

/**
 * A part that is in both states (the capsule's own row inside its panel, the cells beside a tray):
 * it travels with its own group on the body's spring instead of changing with the contents.
 */
export function MorphPart({ name, children }: { name: string; children: React.ReactElement }) {
  return React.cloneElement(children, { 'data-morph-name': `mu-${css(name)}`, 'data-morph-class': 'mu-morph-part' } as Record<string, unknown>);
}

'use client';

import * as React from 'react';

const QUERY = '(prefers-reduced-motion: reduce)';

/** Read the OS preference and MetalUI's motion switch at an element. Safe during SSR. */
export function motionReduced(element?: Element | null): boolean {
  if (typeof window === 'undefined' || typeof document === 'undefined') return false;
  return window.matchMedia(QUERY).matches
    || !!(element ?? document.documentElement).closest('.rm, [data-mu-motion="reduce"]');
}

/** Subscribe to both motion switches, including live changes on a scoped ancestor. */
export function subscribeMotionPreference(element: Element | null | undefined, notify: () => void): () => void {
  if (typeof window === 'undefined' || typeof document === 'undefined') return () => {};
  const media = window.matchMedia(QUERY);
  const observer = new MutationObserver(notify);
  media.addEventListener('change', notify);
  for (let ancestor: Element | null = element ?? document.documentElement; ancestor; ancestor = ancestor.parentElement) {
